def parse_at(v):
    v = str(v).strip()
    if "T" not in v and " " not in v:
        return None
    try:
        t = _dt.datetime.fromisoformat(v[:-1] + "+00:00" if v.endswith("Z") else v)
    except ValueError:
        return None
    return t.replace(tzinfo=TZ) if t.tzinfo is None else t

def hhmm(v):
    try:
        h, m = str(v).split(":")
        if len(m) != 2 or not (0 <= int(h) < 24 and 0 <= int(m) < 60):
